def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (3, 9) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] in (3, 9) and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            comps.append(cells)
    target = min(comps, key=lambda cells: sum(grid[r][c] == 9 for r, c in cells))
    for r, c in target:
        out[r][c] = 0
    return out

